  TR = tr2
}
if tr3 > TR {
  TR = tr3
}

ATR = atr(high, low, close, atrLen)
R = high - low

atrHigh = highest(ATR, coilLookback)
atrLow = lowest(ATR, coilLookback)
atrRange = atrHigh - atrLow
atrCoil = 0.0
if atrRange > 0.000000001 {
  atrCoil = (atrHigh - ATR) / atrRange
}

rHigh = highest(R, coilLookback)
rLow = lowest(R, coilLookback)
rRange = rHigh - rLow
rangeCoil = 0.0
if rRange > 0.000000001 {
  rangeCoil = (rHigh - R) / rRange
}

Load = 100.0 * (atrCoil + rangeCoil) / 2.0

atrSafe = ATR
if atrSafe < 0.000000001 {
  atrSafe = 0.000000001
}
vovRaw = stdev(ATR, vovLookback) / atrSafe
vovRising = vovRaw > vovRaw[1]

pastClose = close[predictLookback]
move = abs(close - pastClose)

path = 0.0
k = 0
