sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 {
    rng := close * 0.01
}
rowSize = rng / rows

binVol = array()
i = 0
while i < rows {
    array.push(binVol, 0.0)
    i := i + 1
}

k = 0
while k < sessLen {
    bHigh = high[k]
    bLow = low[k]
    bVol = volume[k]
    sRow = floor((bLow - sessLow) / rowSize)
    eRow = floor((bHigh - sessLow) / rowSize)
    if sRow < 0 {
        sRow := 0
    }
    if eRow > rows - 1 {
        eRow := rows - 1
    }
    if sRow > rows - 1 {
        sRow := rows - 1
    }
    if eRow < 0 {
        eRow := 0
    }
    bRange = bHigh - bLow
    if bRange <= 0 {
        array.set(binVol, sRow, array.get(binVol, sRow) + bVol)
    } else {
        if sRow == eRow {
            array.set(binVol, sRow, array.get(binVol, sRow) + bVol)
        } else {
            r = sRow
            while r <= eRow {
                rowBot = sessLow + r * rowSize
                rowTop = rowBot + rowSize
                ovTop = rowTop
                if bHigh < ovTop {
                    ovTop := bHigh
                }
                ovBot = rowBot
                if bLow > ovBot {
                    ovBot := bLow
                }
                ov = ovTop - ovBot
                if ov < 0 {
                    ov := 0
                }
                frac = ov / bRange
                array.set(binVol, r, array.get(binVol, r) + bVol * frac)
                r := r + 1
            }
        }
    }
    k := k + 1
}

